/* Main owns navigation progress and table unlocks in one versioned document. */
(function(root){
'use strict';
const key='pinball-main';
function load(storage,themeIds){
 let data;try{data=JSON.parse(storage.getItem(key)||'null');}catch{}
 if(data&&data.version!==1)throw Error('不支援的 main 存檔版本');
 if(!data){
  data={version:1,progress:{},purchased:[]};
  // Import existing saves once; subsequent writes use only pinball-main.
  for(const id of themeIds)try{const old=JSON.parse(storage.getItem(`pinball-${id}-progress-v1`)||'null');const state=data.progress[id]=old||{};state.tutorialComplete=storage.getItem(`pinball-${id}-first-play-tutorial-v1`)==='1';state.seen=[];for(let n=1;n<=8;n++)for(const part of ['start','end']){const chapter=`ch${n}-${part}`;if(storage.getItem(`pinball-${id}-story-seen-v1:${chapter}`)==='1')state.seen.push(chapter);}}catch{}
  try{data.purchased=JSON.parse(storage.getItem('pinball-simulated-purchases-v1')||'[]');}catch{}
 }
 data.progress=data.progress&&typeof data.progress==='object'&&!Array.isArray(data.progress)?data.progress:{};
 data.purchased=Array.isArray(data.purchased)?[...new Set(data.purchased.filter(id=>themeIds.includes(id)))]:[];
 for(const id of themeIds){const old=data.progress[id];data.progress[id]={tutorialComplete:old?.tutorialComplete===true,seen:Array.isArray(old?.seen)?[...new Set(old.seen.filter(s=>/^ch[1-8]-(start|end)$/.test(s)))]:[],cleared:[...new Set(Array.isArray(old?.cleared)?old.cleared.filter(n=>Number.isInteger(n)&&n>=1&&n<=8):[])]};}
 return data;
}
function write(storage,data){storage.setItem(key,JSON.stringify(data));}
const api={key,load,write};if(typeof module!=='undefined')module.exports=api;else root.MainSave=api;
})(globalThis);

