// Lamp sockets in the 1536 x 1024 title artwork; all share one light mask.
const titleLightArtSize=[1536,1024];
const titleLightPositions=[
 [406,290],[577,244],[768,228],[957,245],[1130,291],
 [211,767],[1320,771]
];
let titleLightSprite=null;
function drawTitleLights(ctx,layout){
 if(menuMode!=='main'||menuAnimation)return;
 const title=layout.objects.find(o=>o.type==='image'&&o.src==='res/img/app_title.png');
 if(!title)return;
 const lights=menuImage('res/img/app_light.png');
 if(!lights)return;
 if(!titleLightSprite){
  titleLightSprite=document.createElement('canvas');
  titleLightSprite.width=titleLightSprite.height=280;
  const c=titleLightSprite.getContext('2d');
  // app_light.png contains one complete lamp, shared by every socket.
  c.drawImage(lights,0,0,lights.naturalWidth,lights.naturalHeight,0,0,280,280);
  c.globalCompositeOperation='destination-in';
  const mask=c.createRadialGradient(140,140,45,140,140,140);
  mask.addColorStop(0,'#fff');mask.addColorStop(1,'#fff0');
  c.fillStyle=mask;c.fillRect(0,0,280,280);
 }
 const phase=(performance.now()/1000)%6.4,order=[5,0,1,2,3,4,6];
 ctx.save();ctx.globalCompositeOperation='screen';
 titleLightPositions.forEach(([x,y],i)=>{
  let alpha=.04;
  if(reducedMenuMotion.matches)alpha=.65;
  else if(phase<2.8){
   const head=Math.floor(phase/.2)%7,index=order.indexOf(i);
   if(index===head)alpha=1;
   else if(index===(head+6)%7)alpha=.35;
  }else if(phase<4.8){
   if((order.indexOf(i)+Math.floor((phase-2.8)/.4))%2===0)alpha=1;
  }else{
   const flash=phase-4.8;
   if(flash<.18||(flash>=.4&&flash<.58)||flash>=.9)alpha=1;
  }
  ctx.globalAlpha=alpha;
  ctx.drawImage(titleLightSprite,title.x+(x-140)/titleLightArtSize[0]*title.width,title.y+(y-140)/titleLightArtSize[1]*title.height,280/titleLightArtSize[0]*title.width,280/titleLightArtSize[1]*title.height);
 });
 ctx.restore();
}
